<script setup lang="ts">import{onMounted,ref}from'vue';import{api}from'../api/admin';import{ElMessage}from'element-plus';const data=ref<any>({});const metrics=[['customers','客户总数','统一客户档案'],['orders','订单总数','自营及渠道业务订单'],['iccidAvailable','可用 ICCID','当前可分配库存'],['iccidAssigned','已占用 ICCID','已绑定客户与订单'],['reconciliationExceptions','对账异常','等待人工匹配'],['pendingTasks','待处理任务','需要运营人员跟进'],['pendingSettlements','待确认结算','需要管理员审核']];onMounted(async()=>{try{data.value=await api.dashboard()}catch(e:any){ElMessage.error(e.message)}});</script>
<template><div class="page"><div class="page-heading"><div><h1>业务首页</h1><p>管理端核心业务概览，不展示复杂大屏。</p></div></div><div class="metric-grid"><div v-for="item in metrics" :key="item[0]" class="metric-card"><div class="metric-label">{{item[1]}}</div><div class="metric-value">{{data[item[0]]??'—'}}</div><div class="muted" style="font-size:12px;margin-top:8px">{{item[2]}}</div></div></div><div class="hint-box section-gap"><b>今日处理建议：</b>优先处理对账异常与待确认结算；ICCID 库存不足时及时导入新批次。</div></div></template>

